/**
 * status-widget.test.ts
 * Unit tests for StatusWidget
 */

import { StatusWidget, timeAgo } from '../status-widget';

describe('StatusWidget', () => {
  let mockPi: any;
  let widget: StatusWidget;
  let fetchSpy: jest.Mock;

  beforeEach(() => {
    process.env.RORCA_WORKSPACE_NAME = 'Test Workspace';
    mockPi = {
      ui: {
        setStatus: jest.fn(),
        setWidget: jest.fn(),
      },
    };
    fetchSpy = jest.fn().mockResolvedValue({
      ok: true,
      json: async () => ({
        items: [],
        total: 0,
      }),
    });
    (global as any).fetch = fetchSpy;
    widget = new StatusWidget(mockPi, 'http://localhost:3030');
  });

  afterEach(() => {
    widget.stop();
    delete process.env.RORCA_WORKSPACE_NAME;
    delete process.env.RORCA_TUI_DISABLE;
    delete (global as any).fetch;
    jest.useRealTimers();
    jest.clearAllMocks();
  });

  describe('constructor', () => {
    it('should accept pi, baseUrl, and optional token', () => {
      expect(widget).toBeInstanceOf(StatusWidget);
    });

    it('should strip trailing slash from baseUrl', () => {
      const w = new StatusWidget(mockPi, 'http://localhost:3030/');
      expect(w).toBeInstanceOf(StatusWidget);
    });
  });

  describe('start()', () => {
    it('should respect RORCA_TUI_DISABLE=true', () => {
      process.env.RORCA_TUI_DISABLE = 'true';
      widget.start();
      expect(mockPi.ui.setStatus).not.toHaveBeenCalled();
      expect(fetchSpy).not.toHaveBeenCalled();
    });

    it('should call setStatus immediately with "Connecting..."', () => {
      widget.start();
      expect(mockPi.ui.setStatus).toHaveBeenCalledWith(
        'rorca',
        'Rorca: Connecting...'
      );
    });

    it('should set up polling interval', () => {
      const intervalSpy = jest.spyOn(globalThis, 'setInterval');
      widget.start();
      expect(mockPi.ui.setStatus).toHaveBeenCalledWith('rorca', 'Rorca: Connecting...');
      expect(intervalSpy).toHaveBeenCalledWith(expect.any(Function), 5000);
      intervalSpy.mockRestore();
    });
  });

  describe('stop()', () => {
    it('should clear interval and set disconnected status', () => {
      widget.start();
      mockPi.ui.setStatus.mockClear();
      widget.stop();
      expect(mockPi.ui.setStatus).toHaveBeenCalledWith(
        'rorca',
        'Rorca: Disconnected'
      );
    });

    it('should respect RORCA_TUI_DISABLE=true on stop', () => {
      process.env.RORCA_TUI_DISABLE = 'true';
      widget.start();
      const spy = jest.spyOn(process.stderr, 'write');
      widget.stop();
      expect(spy).not.toHaveBeenCalled();
      spy.mockRestore();
    });
  });

  describe('setActiveRun()', () => {
    it('should accept run state and update internal state', () => {
      widget.setActiveRun(
        123,
        'my-spec',
        10,
        5,
        'anthropic/claude-sonnet-4.5'
      );
      // State is internal, but we can verify no errors thrown
      expect(widget).toBeInstanceOf(StatusWidget);
    });

    it('should accept null values for idle state', () => {
      widget.setActiveRun(null, null, 0, 0, null);
      expect(widget).toBeInstanceOf(StatusWidget);
    });
  });

  describe('timeAgo helper', () => {
    const fixedNow = new Date('2026-05-04T12:00:00Z').getTime();

    it('should return "< 1m" for recent timestamps', () => {
      const nowSpy = jest.spyOn(Date, 'now').mockReturnValue(fixedNow);
      const thirtySecondsAgo = new Date('2026-05-04T11:59:30Z').toISOString();
      expect(timeAgo(thirtySecondsAgo)).toBe('< 1m');
      nowSpy.mockRestore();
    });

    it('should return "Nm ago" for minutes', () => {
      const nowSpy = jest.spyOn(Date, 'now').mockReturnValue(fixedNow);
      const fiveMinutesAgo = new Date('2026-05-04T11:55:00Z').toISOString();
      expect(timeAgo(fiveMinutesAgo)).toBe('5m ago');
      nowSpy.mockRestore();
    });

    it('should return "Nh ago" for hours', () => {
      const nowSpy = jest.spyOn(Date, 'now').mockReturnValue(fixedNow);
      const twoHoursAgo = new Date('2026-05-04T10:00:00Z').toISOString();
      expect(timeAgo(twoHoursAgo)).toBe('2h ago');
      nowSpy.mockRestore();
    });

    it('should handle invalid timestamps gracefully', () => {
      const nowSpy = jest.spyOn(Date, 'now').mockReturnValue(fixedNow);
      expect(timeAgo('invalid')).toBe('< 1m');
      nowSpy.mockRestore();
    });
  });

  describe('fallback mode', () => {
    it('should switch to stderr when setStatus throws', () => {
      mockPi.ui.setStatus = jest.fn(() => {
        throw new Error('Pi UI not available');
      });
      const spy = jest.spyOn(process.stderr, 'write').mockImplementation();

      widget.start();

      expect(spy).toHaveBeenCalledWith(
        expect.stringContaining('[rorca] Rorca: Connecting...')
      );

      spy.mockRestore();
    });

    it('should switch to stderr when setStatus is undefined', () => {
      mockPi.ui.setStatus = undefined;
      const spy = jest.spyOn(process.stderr, 'write').mockImplementation();

      widget.start();

      expect(spy).toHaveBeenCalledWith(
        expect.stringContaining('[rorca]')
      );

      spy.mockRestore();
    });

    it('should still render widget content when setWidget exists but setStatus is unavailable', () => {
      mockPi.ui.setStatus = undefined;
      const spy = jest.spyOn(process.stderr, 'write').mockImplementation();

      widget.start();

      expect(mockPi.ui.setWidget).toHaveBeenCalledWith(
        'rorca-status',
        expect.objectContaining({
          type: 'text',
          title: 'Test Workspace',
          ticker: 'no events',
          content: 'Workspace: Test Workspace\nRorca: Connecting...\nRecent: no events',
        })
      );

      spy.mockRestore();
    });
  });

  describe('widget API (extended)', () => {
    it('should call setWidget if available', () => {
      widget.start();
      expect(mockPi.ui.setWidget).toHaveBeenCalledWith(
        'rorca-status',
        expect.objectContaining({
          type: 'text',
          title: 'Test Workspace',
          ticker: 'no events',
          content: 'Workspace: Test Workspace\nRorca: Connecting...\nRecent: no events',
        })
      );
    });

    it('should not throw if setWidget fails', () => {
      mockPi.ui.setWidget = jest.fn(() => {
        throw new Error('Widget not supported');
      });
      expect(() => widget.start()).not.toThrow();
    });

    it('should include a rolling ticker from the last three WAL events', async () => {
      const nowSpy = jest.spyOn(Date, 'now').mockReturnValue(new Date('2026-05-04T12:00:00Z').getTime());
      global.fetch = jest.fn((url: string) => {
        if (url.includes('/api/wal')) {
          return Promise.resolve({
            ok: true,
            json: async () => ({
              items: [
                { event_type: 'story_passed', ts: '2026-05-04T11:59:30Z' },
                { event_type: 'story_started', ts: '2026-05-04T11:58:00Z' },
                { event_type: 'run_started', ts: '2026-05-04T10:00:00Z' },
              ],
            }),
          } as any);
        }

        return Promise.resolve({
          ok: true,
          json: async () => ({ total: 2 }),
        } as any);
      }) as any;

      await (widget as any).tick();

      expect(mockPi.ui.setWidget).toHaveBeenLastCalledWith(
        'rorca-status',
        expect.objectContaining({
          title: 'Test Workspace',
          ticker: 'story_passed (< 1m)  •  story_started (2m ago)  •  run_started (2h ago)',
          content: [
            'Workspace: Test Workspace',
            'Rorca: Idle — 2 pending | story_passed (< 1m)',
            'Recent: story_passed (< 1m)  •  story_started (2m ago)  •  run_started (2h ago)',
          ].join('\n'),
        })
      );

      expect(global.fetch).toHaveBeenNthCalledWith(
        1,
        'http://localhost:3030/api/wal?limit=3&orderBy=desc',
        expect.objectContaining({
          headers: expect.objectContaining({
            Accept: 'application/json',
          }),
          signal: expect.any(AbortSignal),
        })
      );

      nowSpy.mockRestore();
    });
  });
});

